26	/**
27	 * A foreground service delegate which has client options and connection callback.
28	 */
29	public class ForegroundServiceDelegation {
30	    public final IBinder mBinder = new Binder();
31	    @NonNull
32	    public final ForegroundServiceDelegationOptions mOptions;
33	    @Nullable
34	    public final ServiceConnection mConnection;
