438	    void maybeLogFgsLogicChange() {
439	        final int wiuLegacy = getFgsAllowWiu_legacy();
440	        final int wiuNew = getFgsAllowWiu_new();
441	
442	        final int startLegacy = getFgsAllowStart_legacy();
443	        final int startNew = getFgsAllowStart_new();
444	
445	        final boolean wiuChanged = allowedChanged(wiuLegacy, wiuNew);
446	        final boolean startChanged = allowedChanged(startLegacy, startNew);
447	
448	        if (!wiuChanged && !startChanged) {
449	            return;
450	        }
451	        final String message = "FGS logic changed:"
452	                + (wiuChanged ? " [WIU changed]" : "")
453	                + (startChanged ? " [BFSL changed]" : "")
454	                + " Orig WIU:"
455	                + reasonCodeToString(wiuLegacy)
456	                + " New WIU:"
457	                + reasonCodeToString(wiuNew)
458	                + " Orig BFSL:"
459	                + reasonCodeToString(startLegacy)
460	                + " New BFSL:"
461	                + reasonCodeToString(startNew)
462	                + getFgsInfoForWtf();
463	        Slog.wtf(TAG_SERVICE, message);
464	    }
