550	            proto.write(ServiceRecordProto.StartItem.ID, id);
551	            ProtoUtils.toDuration(proto,
552	                    ServiceRecordProto.StartItem.DURATION, deliveredTime, now);
553	            proto.write(ServiceRecordProto.StartItem.DELIVERY_COUNT, deliveryCount);
554	            proto.write(ServiceRecordProto.StartItem.DONE_EXECUTING_COUNT, doneExecutingCount);
555	            if (intent != null) {
556	                intent.dumpDebug(proto, ServiceRecordProto.StartItem.INTENT, true, true,
557	                        true, false);
