559	            if (neededGrants != null) {
560	                neededGrants.dumpDebug(proto, ServiceRecordProto.StartItem.NEEDED_GRANTS);
561	            }
562	            if (uriPermissions != null) {
563	                uriPermissions.dumpDebug(proto, ServiceRecordProto.StartItem.URI_PERMISSIONS);
564	            }
565	            proto.end(token);
566	        }
