678	    static class TimeLimitedFgsInfo {
679	        @UptimeMillisLong
680	        private long mFirstFgsStartUptime;
681	        // The first fgs start time is maintained here separately in realtime-base
682	        // for the 24-hour window reset logic.
683	        @ElapsedRealtimeLong
684	        private long mFirstFgsStartRealtime;
685	        @UptimeMillisLong
686	        private long mLastFgsStartTime;
687	        @UptimeMillisLong
688	        private long mTimeLimitExceededAt = Long.MIN_VALUE;
689	        @UptimeMillisLong
690	        private long mTotalRuntime = 0;
691	        private int mNumParallelServices = 0;
692	
693	        public void noteFgsFgsStart(@UptimeMillisLong long startTime) {
694	            mNumParallelServices++;
695	            if (mNumParallelServices == 1) {
696	                mFirstFgsStartUptime = startTime;
697	                mFirstFgsStartRealtime = SystemClock.elapsedRealtime();
698	            }
699	            mLastFgsStartTime = startTime;
700	        }
701	
702	        @UptimeMillisLong
703	        public long getFirstFgsStartUptime() {
704	            return mFirstFgsStartUptime;
705	        }
706	
707	        @ElapsedRealtimeLong
708	        public long getFirstFgsStartRealtime() {
709	            return mFirstFgsStartRealtime;
710	        }
711	
712	        @UptimeMillisLong
713	        public long getLastFgsStartTime() {
714	            return mLastFgsStartTime;
715	        }
716	
717	        public void decNumParallelServices() {
718	            if (mNumParallelServices > 0) {
719	                mNumParallelServices--;
720	            }
721	            if (mNumParallelServices == 0) {
722	                mLastFgsStartTime = 0;
723	            }
724	        }
725	
726	        public void updateTotalRuntime(@UptimeMillisLong long nowUptime) {
727	            mTotalRuntime += nowUptime - mLastFgsStartTime;
728	            mLastFgsStartTime = nowUptime;
729	        }
730	
731	        @UptimeMillisLong
732	        public long getTotalRuntime() {
733	            return mTotalRuntime;
734	        }
735	
736	        public void setTimeLimitExceededAt(@UptimeMillisLong long timeLimitExceededAt) {
737	            mTimeLimitExceededAt = timeLimitExceededAt;
738	        }
739	
740	        @UptimeMillisLong
741	        public long getTimeLimitExceededAt() {
742	            return mTimeLimitExceededAt;
743	        }
744	
745	        public void reset() {
746	            mNumParallelServices = 0;
747	            mFirstFgsStartUptime = 0;
748	            mFirstFgsStartRealtime = 0;
749	            mLastFgsStartTime = 0;
750	            mTotalRuntime = 0;
751	            mTimeLimitExceededAt = Long.MIN_VALUE;
752	        }
753	    }
