1213	    public void setProcess(ProcessRecord proc, IApplicationThread thread, int pid,
1214	            UidRecord uidRecord) {
1215	        if (proc != null) {
1216	            // We're starting a new process for this service, but a previous one is allowed to start
1217	            // background activities. Remove that ability now (unless the new process is the same as
1218	            // the previous one, which is a common case).
1219	            if (mAppForAllowingBgActivityStartsByStart != null) {
1220	                if (mAppForAllowingBgActivityStartsByStart != proc) {
1221	                    mAppForAllowingBgActivityStartsByStart
1222	                            .removeBackgroundStartPrivileges(this);
1223	                    ams.mHandler.removeCallbacks(mCleanUpAllowBgActivityStartsByStartCallback);
1224	                }
1225	            }
1226	            // Make sure the cleanup callback knows about the new process.
1227	            mAppForAllowingBgActivityStartsByStart =
1228	                    mBackgroundStartPrivilegesByStartMerged.allowsAny()
1229	                    ? proc : null;
1230	            BackgroundStartPrivileges backgroundStartPrivileges =
1231	                    getBackgroundStartPrivilegesWithExclusiveToken();
1232	            if (backgroundStartPrivileges.allowsAny()) {
1233	                proc.addOrUpdateBackgroundStartPrivileges(this,
1234	                        backgroundStartPrivileges);
1235	            } else {
1236	                proc.removeBackgroundStartPrivileges(this);
1237	            }
1238	        }
1239	        if (app != null && app != proc) {
1240	            // If the old app is allowed to start bg activities because of a service start, leave it
1241	            // that way until the cleanup callback runs. Otherwise we can remove its bg activity
1242	            // start ability immediately (it can't be bound now).
1243	            if (mBackgroundStartPrivilegesByStartMerged.allowsNothing()) {
1244	                app.removeBackgroundStartPrivileges(this);
1245	            }
1246	            app.mServices.updateBoundClientUids();
1247	            app.mServices.updateHostingComonentTypeForBindingsLocked();
1248	        }
1249	        ams.mProcessStateController.setHostProcess(this, proc);
1250	        updateProcessStateOnRequest();
1251	        if (pendingConnectionGroup > 0 && proc != null) {
1252	            final ProcessServiceRecord psr = proc.mServices;
1253	            psr.setConnectionService(this);
1254	            psr.setConnectionGroup(pendingConnectionGroup);
1255	            psr.setConnectionImportance(pendingConnectionImportance);
1256	            pendingConnectionGroup = pendingConnectionImportance = 0;
1257	        }
1258	        if (ActivityManagerService.TRACK_PROCSTATS_ASSOCIATIONS) {
1259	            for (int conni = connections.size() - 1; conni >= 0; conni--) {
1260	                ArrayList<ConnectionRecord> cr = connections.valueAt(conni);
1261	                for (int i = 0; i < cr.size(); i++) {
1262	                    final ConnectionRecord conn = cr.get(i);
1263	                    if (proc != null) {
1264	                        conn.startAssociationIfNeeded();
1265	                    } else {
1266	                        conn.stopAssociation();
1267	                    }
1268	                }
1269	            }
1270	        }
1271	        if (proc != null) {
1272	            proc.mServices.updateBoundClientUids();
1273	            proc.mServices.updateHostingComonentTypeForBindingsLocked();
1274	        }
1275	    }
