1344	    /**
1345	     * Called when the service is started with allowBackgroundActivityStarts set. We allow
1346	     * it for background activity starts, setting up a callback to remove this ability after a
1347	     * timeout. Note that the ability for starting background activities persists for the process
1348	     * even if the service is subsequently stopped.
1349	     */
1350	    void allowBgActivityStartsOnServiceStart(BackgroundStartPrivileges backgroundStartPrivileges) {
1351	        checkArgument(backgroundStartPrivileges.allowsAny());
1352	        mBackgroundStartPrivilegesByStart.add(backgroundStartPrivileges);
1353	        setAllowedBgActivityStartsByStart(
1354	                backgroundStartPrivileges.merge(mBackgroundStartPrivilegesByStartMerged));
1355	        if (app != null) {
1356	            mAppForAllowingBgActivityStartsByStart = app;
1357	        }
1358	
1359	        // This callback is stateless, so we create it once when we first need it.
1360	        if (mCleanUpAllowBgActivityStartsByStartCallback == null) {
1361	            mCleanUpAllowBgActivityStartsByStartCallback = () -> {
1362	                synchronized (ams) {
1363	                    mBackgroundStartPrivilegesByStart.remove(0);
1364	                    if (!mBackgroundStartPrivilegesByStart.isEmpty()) {
1365	                        // recalculate the merged token
1366	                        mBackgroundStartPrivilegesByStartMerged =
1367	                                BackgroundStartPrivileges.merge(mBackgroundStartPrivilegesByStart);
1368	
1369	                        // There are other callbacks in the queue, let's just update the originating
1370	                        // token
1371	                        if (mBackgroundStartPrivilegesByStartMerged.allowsAny()) {
1372	                            // mAppForAllowingBgActivityStartsByStart can be null here for example
1373	                            // if get 2 calls to allowBgActivityStartsOnServiceStart() without a
1374	                            // process attached to this ServiceRecord, so we need to perform a null
1375	                            // check here.
1376	                            if (mAppForAllowingBgActivityStartsByStart != null) {
1377	                                mAppForAllowingBgActivityStartsByStart
1378	                                        .addOrUpdateBackgroundStartPrivileges(this,
1379	                                                getBackgroundStartPrivilegesWithExclusiveToken());
1380	                            }
1381	                        } else {
1382	                            Slog.wtf(TAG,
1383	                                    "Service callback to revoke bg activity starts by service "
1384	                                            + "start triggered but "
1385	                                            + "mBackgroundStartPrivilegesByStartMerged = "
1386	                                            + mBackgroundStartPrivilegesByStartMerged
1387	                                            + ". This should never happen.");
1388	                        }
1389	                    } else {
1390	                        // Last callback on the queue
1391	                        if (app == mAppForAllowingBgActivityStartsByStart) {
1392	                            // The process we allowed is still running the service. We remove
1393	                            // the ability by start, but it may still be allowed via bound
1394	                            // connections.
1395	                            setAllowedBgActivityStartsByStart(BackgroundStartPrivileges.NONE);
1396	                        } else if (mAppForAllowingBgActivityStartsByStart != null) {
1397	                            // The process we allowed is not running the service. It therefore can't
1398	                            // be bound so we can unconditionally remove the ability.
1399	                            mAppForAllowingBgActivityStartsByStart
1400	                                    .removeBackgroundStartPrivileges(ServiceRecord.this);
1401	                        }
1402	                        mAppForAllowingBgActivityStartsByStart = null;
1403	                    }
1404	                }
1405	            };
1406	        }
1407	
1408	        // Existing callbacks will only update the originating token, only when the last callback is
1409	        // executed is the grant revoked.
1410	        ams.mHandler.postDelayed(mCleanUpAllowBgActivityStartsByStartCallback,
1411	                ams.mConstants.SERVICE_BG_ACTIVITY_START_TIMEOUT);
1412	    }
