1708	    public void cancelNotification() {
1709	        // Do asynchronous communication with notification manager to
1710	        // avoid deadlocks.
1711	        final String localPackageName = packageName;
1712	        final int localForegroundId = foregroundId;
1713	        final int appUid = appInfo.uid;
1714	        final int appPid = app != null ? app.getPid() : 0;
1715	        ams.mHandler.post(new Runnable() {
1716	            public void run() {
1717	                NotificationManagerInternal nm = LocalServices.getService(
1718	                        NotificationManagerInternal.class);
1719	                if (nm == null) {
1720	                    return;
1721	                }
1722	                try {
1723	                    nm.cancelNotification(localPackageName, localPackageName, appUid, appPid,
1724	                            null, localForegroundId, userId);
1725	                } catch (RuntimeException e) {
1726	                    Slog.w(TAG, "Error canceling notification for service", e);
1727	                }
1728	                signalForegroundServiceNotification(packageName, appInfo.uid, localForegroundId,
1729	                        true /* canceling */);
1730	            }
1731	        });
1732	    }
