1829	    private boolean shouldTriggerShortFgsTimedEvent(long targetTime, long nowUptime) {
1830	        if (!isAppAlive()) {
1831	            return false;
1832	        }
1833	        if (!this.startRequested || !isShortFgs() || mShortFgsInfo == null
1834	                || !mShortFgsInfo.isCurrent()) {
1835	            return false;
1836	        }
1837	        return targetTime <= nowUptime;
1838	    }
