1898	    private boolean isAppAlive() {
1899	        if (app == null) {
1900	            return false;
1901	        }
1902	        if (app.getThread() == null || app.isKilled() || app.isKilledByAm()) {
1903	            return false;
1904	        }
1905	        return true;
1906	    }
