889	    static String getProcessNameForService(ServiceInfo sInfo, ComponentName name,
890	            String callingPackage, String instanceName, boolean isSdkSandbox,
891	            boolean inSharedIsolatedProcess, boolean inPrivateSharedIsolatedProcess) {
892	        if (isSdkSandbox) {
893	            // For SDK sandbox, the process name is passed in as the instanceName
894	            return instanceName;
895	        }
896	        if ((sInfo.flags & ServiceInfo.FLAG_ISOLATED_PROCESS) == 0
897	                || (inPrivateSharedIsolatedProcess && !isDefaultProcessService(sInfo))) {
898	            // For regular processes, or private package-shared isolated processes, just the name
899	            // in sInfo
900	            return sInfo.processName;
901	        }
902	        // Isolated processes remain.
903	        if (inSharedIsolatedProcess) {
904	            // Shared isolated processes are scoped to the calling package
905	            return callingPackage + ":ishared:" + instanceName;
906	        } else {
907	            return sInfo.processName + ":" + name.getClassName();
908	        }
909	    }
